mapper.select:
SELECT id, receiver, phone, region_code, detail, is_default
FROM user_address WHERE user_id = #{userId}
ORDER BY is_default DESC, id DESC LIMIT #{limit}

mapper.update:
UPDATE user_address
SET receiver = #{address.receiver}, phone = #{address.phone}, region_code = #{address.regionCode},
    detail = #{address.detail}, is_default = #{address.defaultAddress}
WHERE user_id = #{address.userId} AND id = #{addressId}
